write('/faqs','Plumbing FAQs · Service, Repairs & Discounts','Answers about DLR’s 24-hour service, leaks, repairs, service areas, and community discounts.',section('ANSWERS BEFORE ACTION','A little clarity<br>goes a long way.',faq(F))+section('MORE SPECIFIC QUESTIONS','Go deeper into your service.','<div class="related">'+serviceLinks+'</div>','light')+end());
const articles=[
['signs-of-a-hidden-leak','Signs of a hidden plumbing leak','A leak is not always a puddle. Pay attention to changes, then arrange a careful investigation.',[['Watch for changes','An unexplained water-use change, damp patches, staining, or water sounds when fixtures are off can justify investigation. Irrigation and household use can also affect a bill.'],['Document without dismantling','Note dates, locations, and which fixtures were in use. Photograph accessible areas. Do not open walls or handle electrical equipment in a wet area.'],['Ask for a diagnosis','Describe the evidence. Finding the likely source helps guide access and repair options.']],2],
['water-heater-stops-working','When the hot water stops','Useful observations can make the first call more productive.',[['Check the scope','Does it affect one outlet or the whole home? Is water cold, lukewarm, or inconsistent?'],['Keep the area safe','Avoid electrical components if there is water around equipment. Do not attempt unfamiliar gas, electrical, or pressure-related repairs. If you smell gas, leave and contact the appropriate emergency provider from a safe location.'],['Prepare for the call','Have model information and symptoms ready if safely accessible. Discuss repair versus replacement after assessment.']],0],
['recurring-drain-clogs','Why a drain keeps clogging','Repetition is a reason to investigate, not just repeat a temporary fix.',[['Buildup can remain','Grease, soap, hair, and objects restrict different parts of a drain. A partial opening can improve flow without resolving the cause.'],['Look beyond one fixture','Several affected drains can indicate a problem farther along. Stop using fixtures if wastewater backs up.'],['Ask about inspection','A camera may help assess accessible lines after clearing. Visibility and access determine what can be established.']],1],
['planning-a-repipe','Questions to ask before repiping','A clear scope matters as much as the material choice.',[['Understand the recommendation','Ask what condition or history supports repair, partial replacement, or a broader repipe. Age alone is not a diagnosis.'],['Ask about access','Clarify wall or ceiling openings, water interruption expectations, permits, and finish restoration responsibilities.'],['Compare complete scopes','Materials, connections, access, testing, and exclusions affect a proposal. Confirm assumptions before approval.']],7],
['sewer-camera-inspection','What a sewer camera can show','A view inside accessible piping has useful findings and real limitations.',[['A visual tool','A camera can reveal visible buildup, roots, cracking, or displacement where it can pass. It does not see through pipe walls.'],['Access affects results','Standing water, obstructions, and difficult connections can limit travel and visibility. Clearing may be needed first.'],['Use findings in context','Ask where an issue was seen, how it connects to symptoms, and what options the findings support.']],9]];
write('/resources','Plumbing Resources · Practical Guides','Practical guides to hidden leaks, water heaters, recurring clogs, repiping, and sewer inspections.',section('THE HOMEOWNER’S NOTEBOOK','Know a little more.<br>Make a better decision.','<div class="resource-list">'+articles.map(([s,n,intro],i)=>'<a href="/resources/'+s+'/"><span>GUIDE / 0'+(i+1)+'</span><h2>'+n+'</h2><p>'+intro+'</p><b>Read guide ↗</b></a>').join('')+'</div>')+end());
articles.forEach(([slug,name,intro,parts,si])=>write('/resources/'+slug,name,intro,section('HOMEOWNER’S NOTEBOOK',name,'<div class="article-body"><p class="lead">'+intro+'</p>'+parts.map(([h,p])=>'<h2>'+h+'</h2><p>'+p+'</p>').join('')+'<a class="text-link" href="/services/'+services[si].slug+'/">Explore '+services[si].name.toLowerCase()+' ↗</a></div>')+end()));
write('/privacy','Privacy Policy','How this website handles inquiry information, browser preferences, and external links.',section('WEBSITE INFORMATION','Privacy Policy','<div class="article-body"><p>Effective October 26, 2026.</p><h2>Who to contact</h2><p>DLR Plumbing Solutions Inc., Menifee, California. Questions: <a href="mailto:dlrplumbingsolutions@gmail.com">dlrplumbingsolutions@gmail.com</a> or (951) 238-5089.</p><h2>Inquiry information</h2><p>The current form prepares an email in your mail application. Your name, phone, email, city, service selection, preferred contact method, and message are not submitted to a form server by this site. Your email provider handles a message when you choose to send it. DLR uses received information to respond and arrange requested service.</p><h2>Browser storage</h2><p>Session storage may record that you watched or skipped the optional entrance to avoid repeating it during the same session. This site does not install analytics or advertising scripts.</p><h2>Hosting and external sites</h2><p>The hosting provider may process technical request information such as IP address and browser details. Instagram, CSLB, and mail services have their own policies. No Instagram embed loads automatically. The interactive maps request map tiles from OpenStreetMap; that provider receives ordinary request data such as IP address and referring page under its own privacy practices.</p><h2>Your choices</h2><p>Call instead if you prefer. Do not send payment or sensitive information through the form. Contact DLR about access, correction, or deletion of information you provided; applicable obligations may affect retention.</p></div>'));
write('/terms','Website Terms of Service','Terms for website use and DLR plumbing service inquiries.',section('WEBSITE INFORMATION','Terms of Service','<div class="article-body"><p>Effective October 26, 2026.</p><h2>Website information</h2><p>This site explains services and contact methods. General information is not a property-specific assessment. Do not attempt work you cannot perform safely.</p><h2>Inquiries and service agreements</h2><p>An inquiry does not confirm an appointment, price, coverage, or arrival time. Scope, scheduling, costs, and service terms are agreed directly. Discounts depend on current availability and eligibility.</p><h2>Images and content</h2><p>Illustrative images do not depict completed DLR work. Future project photos and reviews must be authorized and accurately attributed.</p><h2>External links</h2><p>External pages are managed by their operators. Check current licensing with CSLB.</p><h2>Contact</h2><p>Questions: <a href="mailto:dlrplumbingsolutions@gmail.com">dlrplumbingsolutions@gmail.com</a>.</p></div>'));
write('/404','Page Not Found','Find DLR plumbing services or call (951) 238-5089.',section('404 / A MISSED CONNECTION','Let’s get you<br>to the right place.','<p>The requested page is unavailable.</p><div class="cta-row"><a class="button navy" href="/">Back to home ↗</a><a class="text-link" href="/services/">Explore services ↗</a></div>'),{noindex:true});
